css:
.stat{position:relative; font-size:90px; font-weight:800; line-height:1; letter-spacing:-.02em; font-feature-settings:"tnum" 1}
.stat .sub{font-size:.55em; vertical-align:baseline}   /* 小数・単位 */
.stat .pre{display:block; font-size:.1em; font-weight:700} /* 「より」など */
.stat .label{position:absolute; left:0; bottom:16px; font-size:13px; letter-spacing:.2em; font-weight:700; color:#2fb894}
.year{font-family:Cormorant,"Noto Serif JP",serif; font-size:2.1rem; line-height:1; color:#b08d3f}
.era{font-size:.62rem; letter-spacing:.06em; color:#b08d3f}
